'use strict';

// MODULES //

var absf = require( '@stdlib/math-base-special-absf' );
var abs2f = require( '@stdlib/math-base-special-abs2f' );
var expf = require( '@stdlib/math-base-special-expf' );
var f32 = require( '@stdlib/number-float64-base-to-float32' );
var MAXLOGF = require( '@stdlib/constants-float32-max-ln' );
var polyvalP = require( './polyval_p.js' );


// VARIABLES //

var ZERO = f32( 0.0 );
var ONE = f32( 1.0 );
var TWO = f32( 2.0 );
var FIVE_EIGHTHS = f32( 0.625 );


// MAIN //

/**
* Computes the hyperbolic tangent of a single-precision floating-point number.
*
* ## Method
*
* For \\( |x| < 0.625 \\), we use a polynomial approximation of the form
*
* ```tex
* x + x^3 \mathrm{P}(x^2)
* ```
*
* Otherwise,
*
* ```tex
* \begin{align*}
* \operatorname{tanhf}(x) &= \frac{\operatorname{sinhf}(x)}{\operatorname{coshf}(x)} \\
* &= 1 - \frac{2}{e^{2x} + 1}
* \end{align*}
* ```
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain | # trials | peak    | rms     |
*     |:----------:|:------:|:--------:|:-------:|:-------:|
*     | IEEE       | -2, 2  | 100000   | 1.3e-7  | 2.6e-8  |
*
* @param {number} x - input value
* @returns {number} hyperbolic tangent
*
* @example
* var v = tanhf( 0.0 );
* // returns 0.0
*
* @example
* var v = tanhf( 2.0 );
* // returns ~0.964
*
* @example
* var v = tanhf( -2.0 );
* // returns ~-0.964
*
* @example
* var v = tanhf( NaN );
* // returns NaN
*/
function tanhf( x ) {
	var s;
	var z;

	x = f32( x );
	z = absf( x );
	if ( z > f32( 0.5 * MAXLOGF ) ) {
		return ( x < ZERO ) ? -ONE : ONE;
	}
	if ( z >= FIVE_EIGHTHS ) {
		s = expf( f32( TWO * z ) );
		z = f32( ONE - f32( TWO / f32( s + ONE ) ) );
		if ( x < ZERO ) {
			z = -z;
		}
		return z;
	}
	if ( x === ZERO ) {
		return x; // Handle `+-0`
	}
	s = abs2f( x );
	return f32( x + f32( f32( x * s ) * polyvalP( s ) ) );
}


// EXPORTS //

module.exports = tanhf;
